tests:
def test_passed_failed_counts():
    assert passed == 3, f"ожидалось passed=3, получено {passed}"
    assert failed == 2, f"ожидалось failed=2, получено {failed}"


def test_failed_tests_list():
    assert failed_tests == ["test_registration", "test_password_reset"], f"неверный список упавших тестов: {failed_tests}"


def test_duration_stats():
    assert total_duration == 915, f"суммарная длительность должна быть 915, получено {total_duration}"
    assert average_duration == 183, f"средняя длительность должна быть округлена до 183, получено {average_duration}"


def test_summary_format():
    expected = "Passed: 3, Failed: 2\nFailed tests: test_registration, test_password_reset\nTotal duration: 915 ms, average: 183 ms"
    assert summary == expected, f"получено:\n{summary}"
